# Retry with exponential backoff and jitter.
import random
import time
from typing import Callable, TypeVar

T = TypeVar("T")

def retry_with_backoff(fn: Callable[[], T], *, max_attempts: int = 5, base_delay: float = 0.5) -> T:
    for attempt in range(1, max_attempts + 1):
        try:
            return fn()
        except Exception:
            if attempt == max_attempts:
                raise
            sleep_for = base_delay * (2 ** (attempt - 1))
            sleep_for += random.uniform(0, base_delay)
            time.sleep(sleep_for)
    raise RuntimeError("unreachable")

// Debounce a function so it only fires after `wait` ms of silence.
export function debounce<F extends (...args: unknown[]) => void>(fn: F, wait: number): F {
  let timer: ReturnType<typeof setTimeout> | null = null;
  return ((...args: Parameters<F>) => {
    if (timer !== null) clearTimeout(timer);
    timer = setTimeout(() => {
      timer = null;
      fn(...args);
    }, wait);
  }) as F;
}

