// worker consumes jobs until ctx is cancelled or the channel closes.
func worker(ctx context.Context, id int, jobs <-chan int, results chan<- int) {
	for {
		select {
		case <-ctx.Done():
			return
		case j, ok := <-jobs:
			if !ok {
				return
			}
			time.Sleep(50 * time.Millisecond)
			results <- j * j
			fmt.Printf("worker %d finished job %d\n", id, j)
		}
	}
}

use std::collections::HashMap;

/// Counts how many times each word appears in `text`, case-insensitive.
pub fn word_count(text: &str) -> HashMap<String, u32> {
    let mut counts = HashMap::new();
    for raw in text.split_whitespace() {
        let word: String = raw
            .chars()
            .filter(|c| c.is_alphanumeric())
            .flat_map(|c| c.to_lowercase())
            .collect();
        if !word.is_empty() {
            *counts.entry(word).or_insert(0) += 1;
        }
    }
    counts
}

from dataclasses import dataclass
from decimal import Decimal

@dataclass(frozen=True)
class LineItem:
    sku: str
    quantity: int
    unit_price: Decimal

    def subtotal(self) -> Decimal:
        return self.unit_price * self.quantity

def order_total(items: list[LineItem], tax_rate: Decimal) -> Decimal:
    subtotal = sum((item.subtotal() for item in items), Decimal("0"))
    tax = (subtotal * tax_rate).quantize(Decimal("0.01"))
    return subtotal + tax

import React, { useEffect, useState } from "react";

export function UserBadge({ userId }: { userId: string }) {
  const [name, setName] = useState<string | null>(null);
  const [error, setError] = useState<Error | null>(null);

  useEffect(() => {
    let cancelled = false;
    fetch(`/api/users/${userId}`)
      .then((r) => (r.ok ? r.json() : Promise.reject(new Error(r.statusText))))
      .then((u) => { if (!cancelled) setName(u.displayName); })
      .catch((e) => { if (!cancelled) setError(e); });
    return () => { cancelled = true; };
  }, [userId]);

  if (error) return <span className="badge err">offline</span>;
  return <span className="badge">{name ?? "…"}</span>;
}

// Clamp a value into the inclusive range [min, max].
function clamp(value, min, max) {
  if (min > max) throw new RangeError("min must be <= max");
  if (value < min) return min;
  if (value > max) return max;
  return value;
}

// Example: clamp the slider input so it never escapes the document's scroll range.
window.addEventListener("scroll", () => {
  const y = clamp(window.scrollY, 0, document.body.scrollHeight - window.innerHeight);
  document.documentElement.style.setProperty("--scroll", String(y));
});

fn fibonacci(n: u32) -> u64 {
    let (mut a, mut b): (u64, u64) = (0, 1);
    for _ in 0..n {
        let next = a.checked_add(b).expect("fibonacci overflowed u64");
        a = b;
        b = next;
    }
    a
}

